class Solution:
    def isValid(self, s: str) -> bool:
        pairs = {")": "(", "]": "[", "}": "{"}
        stack: list[str] = []
        for i, ch in enumerate(s):
            if ch not in pairs:
                stack.append(ch)  # viz:push
            elif stack and stack[-1] == pairs[ch]:  # viz:check
                stack.pop()  # viz:pop
            else:
                return False  # viz:mismatch
        return not stack  # viz:done
